// androidx.sqlite WebWorkerSQLiteDriver'ın konuştuğu worker (protokol: WebWorkerSQLiteDriver KDoc'u).
// Veritabanı OPFS "SAH pool" VFS'inde kalıcıdır; bu VFS COOP/COEP başlığı istemez, her statik sunucuda çalışır.
// OPFS yoksa (ör. gizli pencere) bellekte açılır ve sayfa kapanınca silinir.
import sqlite3InitModule from '@sqlite.org/sqlite-wasm';

let sqlite3 = null;
let pool = null;

const databases = new Map(); // databaseId -> DB
const statements = new Map(); // statementId -> Stmt
let nextDatabaseId = 0;
let nextStatementId = 0;

function reply(id, data) {
    postMessage({ id, data });
}

function fail(id, error) {
    postMessage({ id, error: error.message ?? String(error) });
}

function openRequest(id, request) {
    try {
        const database = pool
            ? new pool.OpfsSAHPoolDb('/' + request.fileName)
            : new sqlite3.oo1.DB(':memory:');
        const databaseId = nextDatabaseId++;
        databases.set(databaseId, database);
        reply(id, { databaseId });
    } catch (error) {
        fail(id, error);
    }
}

function prepareRequest(id, request) {
    const database = databases.get(request.databaseId);
    if (!database) return fail(id, 'Invalid database ID: ' + request.databaseId);
    try {
        const statement = database.prepare(request.sql);
        const statementId = nextStatementId++;
        statements.set(statementId, statement);
        const columnNames = [];
        for (let i = 0; i < statement.columnCount; i++) {
            columnNames.push(sqlite3.capi.sqlite3_column_name(statement, i));
        }
        reply(id, {
            statementId,
            parameterCount: sqlite3.capi.sqlite3_bind_parameter_count(statement),
            columnNames,
        });
    } catch (error) {
        fail(id, error);
    }
}

function stepRequest(id, request) {
    const statement = statements.get(request.statementId);
    if (!statement) return fail(id, 'Invalid statement ID: ' + request.statementId);
    try {
        const rows = [];
        const columnTypes = [];
        statement.reset();
        statement.clearBindings();
        for (let i = 0; i < request.bindings.length; i++) {
            statement.bind(i + 1, request.bindings[i]);
        }
        while (statement.step()) {
            if (!columnTypes.length) {
                for (let i = 0; i < statement.columnCount; i++) {
                    columnTypes.push(sqlite3.capi.sqlite3_column_type(statement, i));
                }
            }
            rows.push(statement.get([]));
        }
        reply(id, { rows, columnTypes });
    } catch (error) {
        fail(id, error);
    }
}

// Tek yönlü: yanıt beklenmez. İstekte biri dolu, diğeri null gelir.
function closeRequest(id, request) {
    if (request.statementId != null) {
        statements.get(request.statementId)?.finalize();
        statements.delete(request.statementId);
    }
    if (request.databaseId != null) {
        databases.get(request.databaseId)?.close();
        databases.delete(request.databaseId);
    }
}

const commands = {
    open: openRequest,
    prepare: prepareRequest,
    step: stepRequest,
    close: closeRequest,
};

function handleMessage(e) {
    const { id, data } = e.data;
    const handler = data && commands[data.cmd];
    if (!handler) return fail(id, 'Invalid request: ' + JSON.stringify(data));
    handler(id, data);
}

const queue = [];
onmessage = (e) => (sqlite3 ? handleMessage(e) : queue.push(e));

sqlite3InitModule().then(async (instance) => {
    try {
        pool = await instance.installOpfsSAHPoolVfs({ name: 'paranoma' });
    } catch (error) {
        console.warn('OPFS yok, veritabanı bellekte açılıyor:', error);
    }
    sqlite3 = instance;
    while (queue.length) handleMessage(queue.shift());
});
